        _fr13_cutlass_dual_foreign_credentials=(
          "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256"
        )
      elif [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4" ]]; then
        _fr13_cutlass_dual_label=two-M
        _fr13_cutlass_dual_tail_json=$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON
        _fr13_cutlass_dual_tail_sha=$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256
        _fr13_cutlass_dual_hydra_json=$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON
        _fr13_cutlass_dual_hydra_sha=$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256
        _fr13_cutlass_dual_foreign_credentials=(
          "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256"
        )
      else
        _fr13_cutlass_dual_label="hybrid N5120"
        _fr13_cutlass_dual_tail_json=$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON
        _fr13_cutlass_dual_tail_sha=$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256
        _fr13_cutlass_dual_hydra_json=$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON
        _fr13_cutlass_dual_hydra_sha=$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256
        _fr13_cutlass_dual_foreign_credentials=(
          "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256"
          "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON"
          "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256"
        )
      fi
      for _fr13_cutlass_dual_foreign in \
        "${_fr13_cutlass_dual_foreign_credentials[@]}"; do
        [[ -z "$_fr13_cutlass_dual_foreign" ]] || {
          echo "CUTLASS $_fr13_cutlass_dual_label production forbids credentials from another candidate" >&2
          exit 2
        }
      done
      [[ "$FR13_FIXED32_CUTLASS_WAVE_PRODUCTION" == "1" \
         && "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_PROFILE" == "k64_root" \
         && -z "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
         && -z "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_SHA256" \
         && "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ ]] || {
        echo "CUTLASS $_fr13_cutlass_dual_label production requires k64_root and a pinned qualification source commit" >&2
        exit 2
      }
      for _fr13_cutlass_dual_pass in \
        "$_fr13_cutlass_dual_tail_json" \
        "$_fr13_cutlass_dual_hydra_json"; do
        [[ "$_fr13_cutlass_dual_pass" == /* \
           && -f "$_fr13_cutlass_dual_pass" \
           && ! -L "$_fr13_cutlass_dual_pass" ]] || {
          echo "CUTLASS $_fr13_cutlass_dual_label production requires regular absolute Tail23 and Hydra27 PASS files" >&2
          exit 2
        }
      done
      [[ "$_fr13_cutlass_dual_tail_sha" =~ ^[0-9a-f]{64}$ \
         && "$_fr13_cutlass_dual_hydra_sha" =~ ^[0-9a-f]{64}$ \
         && "$(sha256sum "$_fr13_cutlass_dual_tail_json" | awk '{print $1}')" == "$_fr13_cutlass_dual_tail_sha" \
         && "$(sha256sum "$_fr13_cutlass_dual_hydra_json" | awk '{print $1}')" == "$_fr13_cutlass_dual_hydra_sha" ]] || {
        if [[ "$_fr13_cutlass_dual_label" == "Stage2" ]]; then
          echo "CUTLASS Stage2 Tail23/Hydra27 PASS identity mismatch" >&2
        elif [[ "$_fr13_cutlass_dual_label" == "two-M" ]]; then
          echo "CUTLASS two-M Tail23/Hydra27 PASS identity mismatch" >&2
        else
          echo "CUTLASS hybrid N5120 Tail23/Hydra27 PASS identity mismatch" >&2
        fi
        exit 2
      }
      _fr13_cutlass_streamk_source_commit=$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT
      _fr13_cutlass_dual_source_commit=$_fr13_cutlass_streamk_source_commit
      .venv/bin/python scripts/fr13_cutlass_b4_pass.py dual-validate \
        --tail23-live-result "$_fr13_cutlass_dual_tail_json" \
        --expected-tail23-live-sha256 "$_fr13_cutlass_dual_tail_sha" \
        --hydra27-live-result "$_fr13_cutlass_dual_hydra_json" \
        --expected-hydra27-live-sha256 "$_fr13_cutlass_dual_hydra_sha" \
        --candidate-so "$FR13_FIXED32_CUTLASS_WAVE_SO" \
        --patch-source scripts/fr13_patch_cutlass_fixed32_wave.py \
        --expected-source-commit "$_fr13_cutlass_dual_source_commit" \
        --candidate-selector "$FR13_FIXED32_CUTLASS_WAVE" \
        --draft-vocab-blocks scripts/fr13_dvk_subset_blocks.json \
        >/dev/null
      unset _fr13_cutlass_dual_pass _fr13_cutlass_dual_label
      unset _fr13_cutlass_dual_tail_json _fr13_cutlass_dual_tail_sha
      unset _fr13_cutlass_dual_hydra_json _fr13_cutlass_dual_hydra_sha
      unset _fr13_cutlass_dual_source_commit
      unset _fr13_cutlass_dual_foreign _fr13_cutlass_dual_foreign_credentials
    else
    [[ "$FR13_FIXED32_CUTLASS_WAVE_PRODUCTION" == "1" \
       && -f "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
       && ! -L "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
       && "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ \
       && -z "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256" ]] || {
      if [[ "$_fr13_cutlass_b4" == "1" ]]; then
        echo "CUTLASS persistent M128 production requires fixed32 B4 and a pinned live PASS" >&2
      else
        echo "CUTLASS Stream-K production requires fixed32 B1 and a pinned live PASS" >&2
      fi
      exit 2
    }
    _fr13_cutlass_runtime_source_args=()
    if [[ "$_fr13_cutlass_b4" == "1" ]]; then
      [[ "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ ]] || {
        echo "CUTLASS persistent M128 production requires a pinned qualification source commit" >&2
        exit 2
      }
      _fr13_cutlass_streamk_source_commit=$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT
    else
      if [[ -n "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT" ]]; then
        [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_wide256_fullgrid_b1" \
           && "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_PROFILE" == "k64_root" \
           && "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT" == "a8a904ed6c27a6338d43151038c155ebb76e3656" ]] || {
          echo "CUTLASS B1 historical qualification is restricted to the pinned cooperative target" >&2
          exit 2
        }
        _fr13_cutlass_streamk_source_commit=$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_SOURCE_COMMIT
        _fr13_cutlass_runtime_source_commit=$(git rev-parse HEAD)
        [[ "$_fr13_cutlass_runtime_source_commit" != "$_fr13_cutlass_streamk_source_commit" ]] || {
          echo "CUTLASS B1 historical qualification requires a newer runtime source" >&2
          exit 2
        }
        _fr13_cutlass_runtime_source_args=(
          --runtime-source-commit "$_fr13_cutlass_runtime_source_commit"
        )
        unset _fr13_cutlass_runtime_source_commit
      else
        _fr13_cutlass_streamk_source_commit=$(git rev-parse HEAD)
      fi
    fi
    _fr13_cutlass_pass_script=scripts/fr13_cutlass_streamk_pass.py
    _fr13_cutlass_pass_profile_args=()
    if [[ "$_fr13_cutlass_b4" == "0" ]]; then
      _fr13_cutlass_pass_profile_args=(
        --qualification-profile "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_PROFILE"
        --diagnostic-task-profile "$FR13_FIXED32_CUTLASS_WAVE_DIAGNOSTIC_TASK_PROFILE"
        --draft-vocab-blocks scripts/fr13_dvk_subset_blocks.json
      )
    else
        _fr13_cutlass_pass_script=scripts/fr13_cutlass_b4_pass.py
        _fr13_cutlass_pass_profile_args=(
          --qualification-profile "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_PROFILE"
          --fixed32-mode "$FR13_FIXED32_MODE"
        )
    fi
    # B1 executes scripts/fr13_cutlass_streamk_pass.py validate; B4 executes
    # the corresponding persistent-M128 credential validator selected above.
    .venv/bin/python "$_fr13_cutlass_pass_script" validate \
      --live-result "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
      --expected-live-sha256 "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_SHA256" \
      --candidate-so "$FR13_FIXED32_CUTLASS_WAVE_SO" \
      --patch-source scripts/fr13_patch_cutlass_fixed32_wave.py \
      --expected-source-commit "$_fr13_cutlass_streamk_source_commit" \
      --candidate-selector "$FR13_FIXED32_CUTLASS_WAVE" \
      "${_fr13_cutlass_pass_profile_args[@]}" \
      "${_fr13_cutlass_runtime_source_args[@]}" \
      >/dev/null
    unset _fr13_cutlass_pass_script
    unset _fr13_cutlass_pass_profile_args
    fi
  fi
  unset _fr13_cutlass_b4
  unset _fr13_cutlass_resource_args
fi
if [[ -n "${FR13_DFWD_UNIFIED_BM8_INTERNAL:-}" ]]; then
  echo "FR13 DFWD unified BM8 internal selector is launcher-private" >&2
