      _fixed32_expected_weight_floor_ms=126.514089260
      ;;
    65536:1)
      _fixed32_expected_draft_vocab_k=65536
      if [[ "$FR13_DRAFT_HEAD_FP8" == "1" ]]; then
        _fixed32_expected_mandatory_weight_bytes=30989326208
