  "$LOG_DIR/fr13_fixed32_cutlass_streamk.production_pass.json" \
  "$LOG_DIR"/fr13_fixed32_cutlass_streamk.production_pass.json.tmp.*
FR13_FIXED32_CUTLASS_WAVE_PRODUCTION_PASS_SIDECAR=""
FR13_FIXED32_CUTLASS_WAVE_PRODUCTION_PASS_SIDECAR_SHA256=""
if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "stock" ]]; then
  rm -f "$LOG_DIR/fr13_fixed32_cutlass_wave.selector"
else
  printf '%s\n' "$FR13_FIXED32_CUTLASS_WAVE" \
    > "$LOG_DIR/fr13_fixed32_cutlass_wave.selector"
  chmod 0444 "$LOG_DIR/fr13_fixed32_cutlass_wave.selector"
fi
if [[ "$FR13_FIXED32_CUTLASS_WAVE_PRODUCTION" == "1" ]]; then
  _fr13_cutlass_streamk_production_sidecar_host="$LOG_DIR/fr13_fixed32_cutlass_streamk.production_pass.json"
  if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_stage2_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4" \
        || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_hybrid_n5120_b4" ]]; then
    if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_stage2_b4" ]]; then
      _fr13_cutlass_dual_tail_json=$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON
      _fr13_cutlass_dual_tail_sha=$FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256
      _fr13_cutlass_dual_hydra_json=$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON
      _fr13_cutlass_dual_hydra_sha=$FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256
    elif [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4" ]]; then
      _fr13_cutlass_dual_tail_json=$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON
      _fr13_cutlass_dual_tail_sha=$FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256
      _fr13_cutlass_dual_hydra_json=$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON
      _fr13_cutlass_dual_hydra_sha=$FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256
    else
      _fr13_cutlass_dual_tail_json=$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON
      _fr13_cutlass_dual_tail_sha=$FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256
      _fr13_cutlass_dual_hydra_json=$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON
      _fr13_cutlass_dual_hydra_sha=$FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256
    fi
    _fr13_cutlass_dual_source_commit=$_fr13_cutlass_streamk_source_commit
    .venv/bin/python scripts/fr13_cutlass_b4_pass.py dual-issue \
      --tail23-live-result "$_fr13_cutlass_dual_tail_json" \
      --expected-tail23-live-sha256 "$_fr13_cutlass_dual_tail_sha" \
      --hydra27-live-result "$_fr13_cutlass_dual_hydra_json" \
      --expected-hydra27-live-sha256 "$_fr13_cutlass_dual_hydra_sha" \
      --candidate-so "$FR13_FIXED32_CUTLASS_WAVE_SO" \
      --patch-source scripts/fr13_patch_cutlass_fixed32_wave.py \
      --expected-source-commit "$_fr13_cutlass_dual_source_commit" \
      --candidate-selector "$FR13_FIXED32_CUTLASS_WAVE" \
      --draft-vocab-blocks scripts/fr13_dvk_subset_blocks.json \
      --out "$_fr13_cutlass_streamk_production_sidecar_host" \
      >/dev/null
    unset _fr13_cutlass_dual_tail_json _fr13_cutlass_dual_tail_sha
    unset _fr13_cutlass_dual_hydra_json _fr13_cutlass_dual_hydra_sha
    unset _fr13_cutlass_dual_source_commit
  else
    _fr13_cutlass_pass_script=scripts/fr13_cutlass_streamk_pass.py
    _fr13_cutlass_pass_profile_args=()
    if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128" ]]; then
      _fr13_cutlass_pass_script=scripts/fr13_cutlass_b4_pass.py
      _fr13_cutlass_pass_profile_args=(
        --qualification-profile "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_PROFILE"
        --fixed32-mode "$FR13_FIXED32_MODE"
      )
    else
      _fr13_cutlass_pass_profile_args=(
        --qualification-profile "$FR13_FIXED32_CUTLASS_WAVE_QUALIFICATION_PROFILE"
        --diagnostic-task-profile "$FR13_FIXED32_CUTLASS_WAVE_DIAGNOSTIC_TASK_PROFILE"
        --draft-vocab-blocks scripts/fr13_dvk_subset_blocks.json
      )
    fi
    # B1 executes scripts/fr13_cutlass_streamk_pass.py issue; legacy B4 M128
    # executes the corresponding B4 issuer selected above.
    .venv/bin/python "$_fr13_cutlass_pass_script" issue \
      --live-result "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
      --expected-live-sha256 "$FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_SHA256" \
      --candidate-so "$FR13_FIXED32_CUTLASS_WAVE_SO" \
      --patch-source scripts/fr13_patch_cutlass_fixed32_wave.py \
      --expected-source-commit "$_fr13_cutlass_streamk_source_commit" \
      --candidate-selector "$FR13_FIXED32_CUTLASS_WAVE" \
      "${_fr13_cutlass_pass_profile_args[@]}" \
      "${_fr13_cutlass_runtime_source_args[@]}" \
      --out "$_fr13_cutlass_streamk_production_sidecar_host" \
      >/dev/null
  fi
  chmod 0400 "$_fr13_cutlass_streamk_production_sidecar_host"
  FR13_FIXED32_CUTLASS_WAVE_PRODUCTION_PASS_SIDECAR=/logs/fr13_fixed32_cutlass_streamk.production_pass.json
  FR13_FIXED32_CUTLASS_WAVE_PRODUCTION_PASS_SIDECAR_SHA256=$(
    sha256sum "$_fr13_cutlass_streamk_production_sidecar_host" | awk '{print $1}'
  )
  unset _fr13_cutlass_streamk_production_sidecar_host
  unset _fr13_cutlass_streamk_source_commit
  unset _fr13_cutlass_pass_script
  unset _fr13_cutlass_pass_profile_args
  unset _fr13_cutlass_runtime_source_args
fi
FR13_FA2_QROW16_PRODUCTION_PASS_SIDECAR=""
FR13_FA2_QROW16_PRODUCTION_PASS_SIDECAR_SHA256=""
if [[ "$FR13_FA2_QROW16_PRODUCTION" == "1" ]]; then
  FR13_FA2_QROW16_PRODUCTION_PASS_SIDECAR_HOST="$LOG_DIR/fr13_fa2_qrow16_production_pass.json"
