  FR13_FIXED32_MIDDLEWARE_FLAGS="--middleware lumo_flywheel_serving.inference_proxy.Fixed32EngineIngressMiddleware"
  rm -f \
    "$LOG_DIR/fr13_fixed32_engine_pid" \
    "$LOG_DIR/fr13_fixed32_flush_request.json" \
    "$LOG_DIR/fr13_fixed32_flush_ack.json" \
    "$LOG_DIR/fr13_fixed32_work_census.jsonl" \
    "$LOG_DIR/fr13_fixed32_engine_ingress.jsonl" \
    "$LOG_DIR/fr13_fixed32_ingress_secret_identity.json" \
    "$LOG_DIR/fr13_fixed32_runtime_attestation.json" \
    "$LOG_DIR"/fr13_fixed32_boundary_snapshot.*.json \
    "$LOG_DIR/fr13_fixed32_committer_layer_batch.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_mode.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_single_launch_tree.arm" \
    "$LOG_DIR/fr13_fixed32_gdn_single_launch_expected_batch.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv_candidate.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv_production.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production.arm" \
    "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_batch.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_credential.json" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv_candidate.flag" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv8.production_engagement.json" \
    "$LOG_DIR"/fr13_fixed32_batch_gdn_bv8.production_engagement.json.tmp.* \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv64.production_engagement.json" \
    "$LOG_DIR"/fr13_fixed32_batch_gdn_bv64.production_engagement.json.tmp.*
  printf '%s\n' "$FR13_FIXED32_MODE" > "$LOG_DIR/fr13_fixed32_mode.flag"
  if [[ -n "$_fr13_gdn_path_bv_candidate" ]]; then
    printf '%s\n' "$_fr13_gdn_path_bv_candidate" \
      > "$LOG_DIR/fr13_fixed32_gdn_path_bv_candidate.flag"
    chmod 400 "$LOG_DIR/fr13_fixed32_gdn_path_bv_candidate.flag"
	    if [[ "$_fr13_gdn_path_bv_candidate" == "single_launch" \
	          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
	          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ]]; then
      printf '%s\n' "$_fr13_gdn_single_launch_expected_batch" \
        > "$LOG_DIR/fr13_fixed32_gdn_single_launch_expected_batch.flag"
      chmod 400 "$LOG_DIR/fr13_fixed32_gdn_single_launch_expected_batch.flag"
    fi
    rm -f "$LOG_DIR/fr13_fixed32_gdn_path_bv.live_pass.json"
  elif [[ -n "$_fr13_gdn_path_bv_production" ]]; then
    cp -- "$_fr13_gdn_path_bv_pass_json" \
      "$LOG_DIR/fr13_fixed32_gdn_path_bv.production_pass.json"
    printf '%s\n' "$_fr13_gdn_path_bv_production" \
      > "$LOG_DIR/fr13_fixed32_gdn_path_bv_production.flag"
    chmod 400 "$LOG_DIR/fr13_fixed32_gdn_path_bv_production.flag"
  elif [[ "$_fr13_gdn_gqa_group3_production" == "1" ]]; then
    cp -- "$_fr13_gdn_gqa_group3_pass_json" \
      "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_credential.json"
    .venv/bin/python \
      scripts/fr13_gdn_gqa_group3_production_credential.py \
      --credential \
      "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_credential.json" \
      --source-commit "$_fr13_gdn_gqa_group3_source_commit" \
      --profile fixed32 \
      --mode "$FR13_FIXED32_MODE" \
      --batch "$_fr13_gdn_gqa_group3_production_batch"
    printf '1\n' \
      > "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production.arm"
    printf '%s\n' "$_fr13_gdn_gqa_group3_production_batch" \
      > "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_batch.flag"
    chmod 400 \
      "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production.arm" \
      "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_batch.flag" \
      "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_credential.json"
  fi
  printf '%s\n' \
    "mode=$FR13_FIXED32_MODE" \
    "pid=$FR13_FIXED32_ENGINE_PID_FILE" \
    "request=$FR13_FIXED32_FLUSH_REQUEST_PATH" \
    "ack=$FR13_FIXED32_FLUSH_ACK_PATH" \
    "census=$FR13_FIXED32_WORK_CENSUS_PATH" \
    "engine_ingress=$FR13_FIXED32_ENGINE_INGRESS_LEDGER_PATH" \
    "boundary=$FR13_FIXED32_BOUNDARY_SNAPSHOT_PATH" \
    > "$LOG_DIR/fr13_fixed32_runtime_paths.txt"
else
  rm -f \
    "$LOG_DIR/fr13_fixed32_mode.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_single_launch_tree.arm" \
    "$LOG_DIR/fr13_fixed32_gdn_single_launch_expected_batch.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv_candidate.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv_production.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production.arm" \
    "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_batch.flag" \
    "$LOG_DIR/fr13_fixed32_gdn_gqa_group3.production_credential.json" \
    "$LOG_DIR/fr13_fixed32_gdn_path_bv.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv_candidate.flag" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv8.production_engagement.json" \
    "$LOG_DIR"/fr13_fixed32_batch_gdn_bv8.production_engagement.json.tmp.* \
    "$LOG_DIR/fr13_fixed32_batch_gdn_bv64.production_engagement.json" \
    "$LOG_DIR"/fr13_fixed32_batch_gdn_bv64.production_engagement.json.tmp.* \
    2>/dev/null || true
fi
# FR13_COMMITTER_NATIVE sidecar (worker-env-drop-proof): the EngineCore worker drops FR13_* env vars, so
# fr10_gdn_tree_kernel reads this sidecar (written here in pid-1 where the env IS present). See its
# _fr13_committer_native_on(). Removed when the flag is off so a stale file can't leak into a later boot.
if [[ "${FR13_COMMITTER_NATIVE:-1}" == "1" ]]; then
  : > "$LOG_DIR/fr13_committer_native.flag"
else
  rm -f "$LOG_DIR/fr13_committer_native.flag" 2>/dev/null || true
fi
# FR13_REPLAY_MULTISTREAM sidecar (worker-env-drop-proof): the worker curation drops FR13_* env, so the
# patched committer reads THIS sidecar (content = N streams) to enable stream-overlapped per-layer replay.
# Absent => serial per-layer loop (byte-identical). This is why the env-only gate went vacuous at B=4.
if [[ "${FR13_REPLAY_MULTISTREAM:-0}" == "1" ]]; then
  echo "${FR13_REPLAY_MULTISTREAM_N:-4}" > "$LOG_DIR/fr13_replay_multistream.arm"
else
  rm -f "$LOG_DIR/fr13_replay_multistream.arm" 2>/dev/null || true
fi
# FR13_COMMIT_OVERLAP sidecar (same worker-env-drop workaround): the committer-
# region overlap gate (side-stream replay+remap under the drafter) reads this
# sidecar, NOT os.environ (the env-only read is exactly what made
# FR13_REPLAY_MULTISTREAM vacuous at B=4). Absent => serial committer
# (byte-identical shipped behavior).
if [[ "${FR13_COMMIT_OVERLAP:-0}" == "1" ]]; then
  echo "1" > "$LOG_DIR/fr13_commit_overlap.arm"
else
  rm -f "$LOG_DIR/fr13_commit_overlap.arm" 2>/dev/null || true
fi
# FR13_COMMITTER_BATCHED / FR13_COMMITTER_GRAPH sidecars (same worker-env-drop
# workaround): arm the sampled-path batched dispatch (sbr gate) + the kernel-lib
# all-layers batched/graph branch. Absent => per-layer serial loop (byte-identical
# shipped behavior). Graph implies the sbr gate too (patcher checks both files).
if [[ "${FR13_COMMITTER_BATCHED:-1}" == "1" ]]; then  # BAKED default-ON 2026-07-23: tail6_batched_f70 16-task gate PASS (span 47->36ms, verify flat, comb 3.592, 8P/8F)
  echo "1" > "$LOG_DIR/fr13_committer_batched.arm"
else
  rm -f "$LOG_DIR/fr13_committer_batched.arm" 2>/dev/null || true
fi
if [[ "${FR13_COMMITTER_GRAPH:-0}" == "1" ]]; then
  echo "1" > "$LOG_DIR/fr13_committer_graph.arm"
else
  rm -f "$LOG_DIR/fr13_committer_graph.arm" 2>/dev/null || true
fi
# FR13_CFWD_CAPTURE_REMAINDER folds the committer fill into the committer graph
# (attack ladder lever 3). Default OFF; the sidecar is removed when unarmed so a
# prior ON boot cannot leak into this one.
if [[ "${FR13_CFWD_CAPTURE_REMAINDER:-0}" == "1" ]]; then
  echo "1" > "$LOG_DIR/fr13_cfwd_capture_remainder.arm"
else
  rm -f "$LOG_DIR/fr13_cfwd_capture_remainder.arm" 2>/dev/null || true
fi
# The batched-GDN byte gates stay reference-served until a real SWE-Verified
# task is explicitly armed after readiness. The EngineCore worker sees these
# /logs sidecars even when its curated environment drops FR13_*.
_fr13_batch_gdn_byte_ab="${FR13_FIXED32_BATCH_GDN_BYTE_AB:-0}"
_fr13_batch_gdn_graph_byte_ab="${FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB-0}"
_fr13_batch_gdn_production="${FR13_FIXED32_BATCH_GDN_PRODUCTION:-0}"
_fr13_batch_gdn_bv_candidate="${FR13_FIXED32_BATCH_GDN_BV_CANDIDATE:-}"
_fr13_batch_gdn_bv_production="${FR13_FIXED32_BATCH_GDN_BV_PRODUCTION:-}"
_fr13_batch_gdn_bv8_timing="${FR13_FIXED32_BATCH_GDN_BV8_TIMING:-0}"
case "$_fr13_batch_gdn_byte_ab" in
  0|1) ;;
  *) echo "FR13_FIXED32_BATCH_GDN_BYTE_AB must be 0 or 1" >&2; exit 2 ;;
esac
case "$_fr13_batch_gdn_graph_byte_ab" in
  0|1) ;;
  *) echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB must be 0 or 1" >&2; exit 2 ;;
esac
case "$_fr13_batch_gdn_production" in
  0|1) ;;
  *) echo "FR13_FIXED32_BATCH_GDN_PRODUCTION must be 0 or 1" >&2; exit 2 ;;
esac
case "$_fr13_batch_gdn_bv_candidate" in
  ""|8|16|32|64|128) ;;
  *) echo "FR13 fixed32 batched GDN diagnostic BV must be 8, 16, 32, 64, or 128" >&2; exit 2 ;;
esac
case "$_fr13_batch_gdn_bv_production" in
  ""|8|64) ;;
  *) echo "FR13 fixed32 batched GDN production BV must be 8 or 64" >&2; exit 2 ;;
esac
if [[ "$_fr13_batch_gdn_bv8_timing" == "1" ]]; then
  if [[ "$MAX_NUM_SEQS" != "4" \
        || "${FR13_FIXED32_MODE:-}" != "hydra27_fixed32" \
        || "${ENFORCE_EAGER:-0}" != "0" \
        || "${CUDAGRAPH_MODE:-}" != "FULL_AND_PIECEWISE" \
        || "$_fr13_batch_gdn_byte_ab" != "0" \
        || "$_fr13_batch_gdn_graph_byte_ab" != "0" \
        || -n "$_fr13_batch_gdn_bv_candidate" \
        || ! ( ( "$_fr13_batch_gdn_production" == "0" \
                 && -z "$_fr13_batch_gdn_bv_production" ) \
                || ( "$_fr13_batch_gdn_production" == "1" \
                     && "$_fr13_batch_gdn_bv_production" == "8" ) ) ]]; then
    echo "FR13_FIXED32_BATCH_GDN_BV8_TIMING requires exact B4 Hydra fixed32 FULL-graph stock or qualified BV8 production" >&2
    exit 2
  fi
fi
_fr13_batch_gdn_diagnostic_count=$((
  10#$_fr13_batch_gdn_byte_ab + 10#$_fr13_batch_gdn_graph_byte_ab
))
if (( _fr13_batch_gdn_diagnostic_count > 1 )); then
  echo "FR13 fixed32 eager and graph batched GDN diagnostics are mutually exclusive" >&2
  exit 2
fi
if [[ -n "$_fr13_batch_gdn_bv_candidate" \
      && -n "$_fr13_batch_gdn_bv_production" ]]; then
  echo "FR13 fixed32 batched GDN wide-BV diagnostic and production selectors are mutually exclusive" >&2
  exit 2
fi
if [[ ( "$_fr13_batch_gdn_byte_ab" == "1" \
        || "$_fr13_batch_gdn_graph_byte_ab" == "1" ) \
      && "$_fr13_batch_gdn_production" == "1" ]]; then
  echo "FR13 fixed32 batched GDN diagnostic and production are mutually exclusive" >&2
  exit 2
fi
if [[ ( -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" ) \
      && ( "$_fr13_batch_gdn_byte_ab" == "1" \
           || "$_fr13_batch_gdn_graph_byte_ab" == "1" \
           || "$_fr13_batch_gdn_production" == "1" ) ]]; then
  echo "FR13 fixed32 batched GDN and path-BV selectors are mutually exclusive" >&2
  exit 2
fi
if [[ ( -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" ) \
      && ( -n "$_fr13_batch_gdn_bv_candidate" \
           || -n "$_fr13_batch_gdn_bv_production" ) ]]; then
  echo "FR13 fixed32 B1 path-BV and B2-B4 batched wide-BV selectors are mutually exclusive" >&2
  exit 2
fi
if [[ -n "$_fr13_batch_gdn_bv_candidate" ]] \
    && (( _fr13_batch_gdn_diagnostic_count != 1 )); then
  echo "FR13_FIXED32_BATCH_GDN_BV_CANDIDATE requires exactly one eager or graph byte diagnostic" >&2
  exit 2
fi
if [[ "$_fr13_batch_gdn_bv_candidate" == "8" \
      && "$_fr13_batch_gdn_graph_byte_ab" != "1" ]]; then
  echo "FR13 fixed32 batched BV8 structure candidate requires the exact-B4 graph diagnostic" >&2
  exit 2
fi
if [[ -n "$_fr13_batch_gdn_bv_production" \
      && "$_fr13_batch_gdn_production" != "1" ]]; then
  echo "FR13_FIXED32_BATCH_GDN_BV_PRODUCTION requires FR13_FIXED32_BATCH_GDN_PRODUCTION=1" >&2
  exit 2
fi
if [[ "$_fr13_batch_gdn_production" != "1" \
      && ( -n "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
           || -n "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
           || -n "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
           || -n "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
           || -n "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
           || -n "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" ) ]]; then
  echo "FR13 fixed32 B4 GDN graph PASS inputs require the production selector" >&2
  exit 2
fi
rm -f \
  "$LOG_DIR/fr13_fixed32_batch_gdn_bv_candidate.flag" \
  "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag" \
  2>/dev/null || true
if [[ "$_fr13_batch_gdn_byte_ab" == "1" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_BYTE_AB requires FR13_FIXED32_MODE" >&2; exit 2; }
  [[ "${ENFORCE_EAGER:-0}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_BYTE_AB requires ENFORCE_EAGER=1" >&2; exit 2; }
  [[ "${FR10_METRICS:-0}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_BYTE_AB requires FR10_METRICS=1" >&2; exit 2; }
  [[ "${FR13_RING_EXPORT:-1}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_BYTE_AB requires FR13_RING_EXPORT=1" >&2; exit 2; }
  [[ "${FR13_FLAGS_INKERNEL:-1}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_BYTE_AB requires FR13_FLAGS_INKERNEL=1" >&2; exit 2; }
  [[ "$MAX_NUM_SEQS" =~ ^[234]$ ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_BYTE_AB requires MAX_NUM_SEQS=2, 3, or 4" >&2; exit 2; }
  echo "1" > "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.enabled"
else
  rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.enabled" 2>/dev/null || true
fi
if [[ "$_fr13_batch_gdn_graph_byte_ab" == "1" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB requires FR13_FIXED32_MODE" >&2; exit 2; }
  [[ "${ENFORCE_EAGER:-0}" == "0" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB requires ENFORCE_EAGER=0" >&2; exit 2; }
  [[ "${FR10_METRICS:-0}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB requires FR10_METRICS=1" >&2; exit 2; }
  [[ "${FR13_RING_EXPORT:-1}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB requires FR13_RING_EXPORT=1" >&2; exit 2; }
  [[ "${FR13_FLAGS_INKERNEL:-1}" == "1" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB requires FR13_FLAGS_INKERNEL=1" >&2; exit 2; }
  [[ "$MAX_NUM_SEQS" == "4" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB requires MAX_NUM_SEQS=4" >&2; exit 2; }
  [[ "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_GRAPH_BYTE_AB is incompatible with the B1 diagnostic" >&2; exit 2; }
  echo "1" > "$LOG_DIR/fr13_fixed32_batch_gdn_graph_byte_ab.enabled"
else
  rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_graph_byte_ab.enabled" 2>/dev/null || true
fi
if (( _fr13_batch_gdn_diagnostic_count == 1 )) \
    || [[ "$_fr13_gdn_path_bv_candidate" == "single_launch" \
          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
          || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ]]; then
  if [[ "$_fr13_gdn_path_bv_candidate" == "single_launch" \
        || "$_fr13_gdn_path_bv_candidate" == "gqa_group3" \
        || "$_fr13_gdn_path_bv_candidate" == "gqa_group3_bv16" ]]; then
    echo "1" > "$LOG_DIR/fr13_fixed32_batch_gdn_graph_byte_ab.enabled"
  fi
  if [[ -n "$_fr13_batch_gdn_bv_candidate" ]]; then
    printf '%s\n' "$_fr13_batch_gdn_bv_candidate" \
      > "$LOG_DIR/fr13_fixed32_batch_gdn_bv_candidate.flag"
    chmod 400 "$LOG_DIR/fr13_fixed32_batch_gdn_bv_candidate.flag"
  fi
  rm -f \
    "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json"
  FR13_FIXED32_BATCH_GDN_BYTE_AB_REAL_EVENT_PATH=/logs/fr13_fixed32_batch_gdn_byte_ab.real_event.arm
else
  rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.real_event.arm" 2>/dev/null || true
  FR13_FIXED32_BATCH_GDN_BYTE_AB_REAL_EVENT_PATH=
fi
export FR13_FIXED32_BATCH_GDN_BYTE_AB_REAL_EVENT_PATH
_fr13_cutlass_b4_byte_ab=0
if [[ "$FR13_FIXED32_CUTLASS_WAVE" == "identity_divisor_b4_byte_ab" \
      || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_b4_byte_ab" \
      || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_stockshape_stage2_b4_byte_ab" \
      || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_twom_b4_byte_ab" \
      || "$FR13_FIXED32_CUTLASS_WAVE" == "identity_hybrid_n5120_b4_byte_ab" \
      || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_byte_ab" \
      || "$FR13_FIXED32_CUTLASS_WAVE" == "persistent_b4_m128_static_byte_ab" ]]; then
  _fr13_cutlass_b4_byte_ab=1
fi
if [[ "$_fr13_cutlass_b4_byte_ab" == "1" ]]; then
  [[ "$_fr13_batch_gdn_diagnostic_count" == "0" \
     && "$MAX_NUM_SEQS" == "4" \
     && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
     && "${ENFORCE_EAGER:-0}" == "1" ]] || {
    echo "CUTLASS B4 byte A/B requires exclusive eager exact-B4 diagnostics" >&2
    exit 2
  }
  printf '1\n' > "$LOG_DIR/fr13_fixed32_cutlass_b4_byte_ab.enabled"
  rm -f "$LOG_DIR/fr13_fixed32_cutlass_b4_byte_ab.real_event.arm"
  FR13_FIXED32_CUTLASS_B4_BYTE_AB_REAL_EVENT_PATH=/logs/fr13_fixed32_cutlass_b4_byte_ab.real_event.arm
else
  rm -f \
    "$LOG_DIR/fr13_fixed32_cutlass_b4_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_cutlass_b4_byte_ab.real_event.arm" \
    2>/dev/null || true
  FR13_FIXED32_CUTLASS_B4_BYTE_AB_REAL_EVENT_PATH=
fi
export FR13_FIXED32_CUTLASS_B4_BYTE_AB_REAL_EVENT_PATH
unset _fr13_cutlass_b4_byte_ab
_fr13_sfwd_b4_byte_ab=${FR13_FIXED32_SFWD_STATE_FUSION_BYTE_AB:-0}
_fr13_sfwd_state_fusion_timing="${FR13_FIXED32_SFWD_STATE_FUSION_TIMING_AB:-0}"
_fr13_sfwd_production=${FR13_FIXED32_SFWD_STATE_FUSION_PRODUCTION:-0}
_fr13_sfwd_prior_reuse=${FR13_FIXED32_SFWD_PRIOR_REUSE_BYTE_AB:-0}
_fr13_sfwd_conv_postprep=${FR13_FIXED32_SFWD_CONV_POSTPREP_FUSION:-0}
_fr13_sfwd_conv_postprep_byte=${FR13_FIXED32_SFWD_CONV_POSTPREP_BYTE_AB:-0}
_fr13_sfwd_embed_gate=${FR13_FIXED32_SFWD_EMBED_GATE_CTA:-0}
_fr13_sfwd_nodegroup8_direct=${FR13_FIXED32_SFWD_NODEGROUP8_DIRECT:-0}
for _fr13_sfwd_selector in \
  "$_fr13_sfwd_b4_byte_ab" \
  "$_fr13_sfwd_state_fusion_timing" \
  "$_fr13_sfwd_production" \
  "$_fr13_sfwd_prior_reuse" \
  "$_fr13_sfwd_conv_postprep" \
  "$_fr13_sfwd_conv_postprep_byte"; do
  case "$_fr13_sfwd_selector" in
    0|1) ;;
    *) echo "FR13 SFWD selectors must be exactly 0 or 1" >&2; exit 2 ;;
  esac
done
case "$_fr13_sfwd_embed_gate" in
  0|1) ;;
  *) echo "FR13_FIXED32_SFWD_EMBED_GATE_CTA must be exactly 0 or 1" >&2; exit 2 ;;
esac
case "$_fr13_sfwd_nodegroup8_direct" in
  0|1) ;;
  *) echo "FR13_FIXED32_SFWD_NODEGROUP8_DIRECT must be exactly 0 or 1" >&2; exit 2 ;;
esac
[[ "$_fr13_sfwd_embed_gate" == "0" \
   || ( ( "$_fr13_sfwd_conv_postprep_byte" == "1" \
          || "$_fr13_sfwd_conv_postprep" == "1" ) \
        && "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ) ]] || {
  echo "embedded gate CTA requires Hydra27 conv/post-prep production or byte gate" >&2
  exit 2
}
[[ "$_fr13_sfwd_nodegroup8_direct" == "0" \
   || ( "$_fr13_sfwd_conv_postprep_byte" == "1" \
        && "$_fr13_sfwd_conv_postprep" == "0" \
        && "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
        && "${MAX_NUM_SEQS:-}" == "1" \
        && "${SWE_CONCURRENCY:-}" == "1" ) ]] || {
  echo "direct nodegroup8 requires the Hydra27 B1 conv/post-prep byte gate" >&2
  exit 2
}
_fr13_sfwd_route_count=$((
  10#$_fr13_sfwd_b4_byte_ab
  + 10#$_fr13_sfwd_state_fusion_timing
  + 10#$_fr13_sfwd_production
  + 10#$_fr13_sfwd_prior_reuse
  + 10#$_fr13_sfwd_conv_postprep
  + 10#$_fr13_sfwd_conv_postprep_byte
))
if (( _fr13_sfwd_route_count > 1 )); then
  echo "FR13 SFWD diagnostics and production are mutually exclusive" >&2
  exit 2
fi
if [[ "$_fr13_sfwd_conv_postprep" == "1" ]]; then
  _fr13_sfwd_conv_postprep_execution=invalid
  if [[ "${ENFORCE_EAGER:-0}" == "1" ]]; then
    _fr13_sfwd_conv_postprep_execution=eager
  elif [[ "${ENFORCE_EAGER:-0}" == "0" \
          && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" ]]; then
    _fr13_sfwd_conv_postprep_execution=full_graph
  fi
  _fr13_sfwd_qrow16_production=0
  if [[ "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" == "0" \
        && "${FR13_FA2_QROW16_PRODUCTION:-0}" == "1" \
        && "${FR13_FA2_QROW16_SO_SHA256:-}" == "1649fbe9c6886147710dc9be97567bffcac36175c26742b752be9be50c2cbb86" \
        && "${FR13_FA2_QROW16_LIVE_PASS_SHA256:-}" == "36940fd43d11399529d1bfe7e11baa9961907193267f3bb43d41057328737b77" \
        && -z "${FR13_FA2_QROW32_B1_LIVE_AB_ARM:-}" \
        && -z "${FR13_FA2_QROW32_B1_PRODUCTION_ARM:-}" ]]; then
    _fr13_sfwd_qrow16_production=1
  fi
  _fr13_sfwd_qrow32_production=0
  if [[ "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" == "0" \
        && "${FR13_FA2_QROW16_PRODUCTION:-0}" == "0" \
        && -z "${FR13_FA2_QROW32_B1_LIVE_AB_ARM:-}" \
        && "${FR13_FA2_QROW32_B1_PRODUCTION_ARM:-}" == "nosplit" \
        && "${FR13_FA2_QROW32_B1_SO_SHA256:-}" == "a9d8a6887b8b27b3a83af60bba7945eb66caff174ba710c2ee2aea92b8e7081a" \
        && "${FR13_FA2_QROW32_B1_SO_SIZE:-}" == "300154616" ]]; then
    _fr13_sfwd_qrow32_production=1
  fi
  _fr13_sfwd_cutlass_production=0
  case "${FR13_FIXED32_CUTLASS_WAVE:-stock}" in
    stock)
      [[ "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION:-0}" == "0" ]] \
        || { echo "SFWD conv/post-prep stock CUTLASS cannot carry production authority" >&2; exit 2; }
      ;;
    identity_onen_n5120_fullgrid_b1|identity_wide256_fullgrid_b1)
      [[ "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION:-0}" == "1" ]] \
        || { echo "SFWD conv/post-prep target-GEMM selector requires production authority" >&2; exit 2; }
      _fr13_sfwd_cutlass_production=1
      ;;
    *)
      echo "SFWD conv/post-prep permits only stock or a credentialed B1 full-grid target GEMM" >&2
      exit 2
      ;;
  esac
  _fr13_sfwd_cfwd_composed=0
  if [[ "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
        && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
        && "$_fr13_sfwd_qrow16_production" == "0" \
        && "$_fr13_sfwd_qrow32_production" == "1" \
        && "${FR13_FIXED32_GDN_GQA_GROUP3_PRODUCTION:-0}" == "1" \
        && "${FR13_FIXED32_GDN_GQA_GROUP3_PRODUCTION_BATCH:-}" == "1" \
        && "${FR13_DFWD_K64_TOP3:-0}" == "1" \
        && "${FR13_DFWD_K64_TOP3_SHA256:-}" == "c0ed75cafdd926eceafcf28671869d54f37addb51bfef5a37c0b07c34f5420ff" \
        && "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "identity_wide256_fullgrid_b1" \
        && "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION:-0}" == "1" \
        && "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE:-0}" == "0" \
        && "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE_PRODUCTION:-0}" == "1" \
        && "${FR13_CFWD_LOGIT_DIRECT_BYTE_AB:-0}" == "0" \
        && "${FR13_CFWD_LOGIT_DIRECT_PRODUCTION:-0}" == "1" ]]; then
    _fr13_sfwd_cfwd_composed=1
  fi
  _fr13_sfwd_u8_cfwd_composed=$_fr13_b1_u8_cfwd_sfwd_stack
  _fr13_sfwd_conv_postprep_profile=invalid
  if [[ "$MAX_NUM_SEQS" == "1" \
        && "${SWE_CONCURRENCY:-}" == "1" \
        && ( $((10#$_fr13_sfwd_qrow16_production + 10#$_fr13_sfwd_qrow32_production)) == 1 \
             || "$_fr13_sfwd_u8_cfwd_composed" == "1" ) ]]; then
    _fr13_sfwd_conv_postprep_profile=b1
  elif [[ "$_fr13_sfwd_embed_gate" == "1" \
          && "$MAX_NUM_SEQS" == "4" \
          && "${SWE_CONCURRENCY:-}" == "4" \
          && "$_fr13_sfwd_qrow16_production" == "0" \
          && "$_fr13_sfwd_qrow32_production" == "0" \
          && "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "stock" \
          && "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION:-0}" == "0" ]]; then
    _fr13_sfwd_conv_postprep_profile=embedded_b4
  fi
  if [[ ( "${FR13_FIXED32_MODE:-}" != "tail6_fixed32" \
          && "${FR13_FIXED32_MODE:-}" != "hydra27_fixed32" ) \
        || "$_fr13_sfwd_conv_postprep_profile" == "invalid" \
        || "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" != "0" \
        || "$_fr13_sfwd_conv_postprep_execution" == "invalid" \
        || ( "$_fr13_sfwd_embed_gate" == "1" \
             && "$_fr13_sfwd_conv_postprep_execution" != "eager" ) \
        || "${FR13_DRAFT_VOCAB_ROOT:-0}" != "1" \
        || "${FR13_DRAFT_VOCAB_K:-65536}" != "65536" \
        || "${FR13_DRAFT_VOCAB_BLOCKS:-}" != "/workspace/scripts/fr13_dvk_subset_blocks.json" \
        || "${FR13_RING_EXPORT:-1}" != "1" \
        || "${FR13_FLAGS_INKERNEL:-1}" != "1" \
        || "${FR13_TREE_RUNROW_INIT:-1}" != "1" \
        || "${FR13_TREE_CONV_FUSED:-1}" != "1" \
        || "${FR13_CONV_WB_BATCHED:-0}" != "1" \
        || "${FR13_FIXED32_CONV_SOURCE_BATCH:-0}" != "0" ]]; then
    echo "SFWD conv/post-prep production requires exact K64/root1 B1, or source-qualified embedded Hydra27 eager B1/B4" >&2
    exit 2
  fi
  if [[ "$_fr13_batch_gdn_diagnostic_count" != "0" \
        || "$_fr13_batch_gdn_production" != "0" \
        || -n "$_fr13_batch_gdn_bv_candidate" \
        || -n "$_fr13_batch_gdn_bv_production" \
        || -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" \
        || "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" != "0" \
        || "${FR13_DRAFT_HEAD_M32_PRODUCTION:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE:-0}" != "0" \
        || ( "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE_PRODUCTION:-0}" != "0" \
             && "$_fr13_sfwd_cfwd_composed" != "1" \
             && "$_fr13_sfwd_u8_cfwd_composed" != "1" ) \
        || "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_PRODUCTION:-0}" != "0" ]]; then
    echo "SFWD conv/post-prep production inherited an incompatible diagnostic or production arm" >&2
    exit 2
  fi
  [[ "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH" == /workspace/* \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_JSON" == /workspace/* \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_COMMIT" == "$(git rev-parse HEAD)" ]] || {
    echo "SFWD conv/post-prep production requires source-bound PASS credentials" >&2
    exit 2
  }
  _fr13_sfwd_conv_manifest_host="$REPO/${FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH#/workspace/}"
  _fr13_sfwd_conv_pass_host="$REPO/${FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_JSON#/workspace/}"
  [[ -f "$_fr13_sfwd_conv_manifest_host" \
     && ! -L "$_fr13_sfwd_conv_manifest_host" \
     && "$(stat -c '%h' "$_fr13_sfwd_conv_manifest_host")" == "1" \
     && "$(sha256sum "$_fr13_sfwd_conv_manifest_host" | awk '{print $1}')" == "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_SHA256" \
     && -f "$_fr13_sfwd_conv_pass_host" \
     && ! -L "$_fr13_sfwd_conv_pass_host" \
     && "$(stat -c '%h' "$_fr13_sfwd_conv_pass_host")" == "1" \
     && "$(sha256sum "$_fr13_sfwd_conv_pass_host" | awk '{print $1}')" == "$FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_SHA256" ]] || {
    echo "SFWD conv/post-prep production PASS or source manifest changed" >&2
    exit 2
  }
  python3 scripts/fr13_sfwd_conv_postprep_gate.py validate-pass \
    --repo "$REPO" \
    --live-pass "$_fr13_sfwd_conv_pass_host" \
    --expected-live-pass-sha256 "$FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_SHA256" \
    --source-manifest "$_fr13_sfwd_conv_manifest_host" \
    --expected-source-manifest-sha256 "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_SHA256" \
    --source-commit "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_COMMIT"
  cp -- "$_fr13_sfwd_conv_manifest_host" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.source_manifest.json"
  cp -- "$_fr13_sfwd_conv_pass_host" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.production_pass.json"
  chmod 0400 \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.source_manifest.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.production_pass.json"
  FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH=/logs/fr13_fixed32_sfwd_conv_postprep.source_manifest.json
  FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_JSON=/logs/fr13_fixed32_sfwd_conv_postprep.production_pass.json
  FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH=
  FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH=
  unset _fr13_sfwd_qrow16_production _fr13_sfwd_qrow32_production
  unset _fr13_sfwd_cutlass_production
  unset _fr13_sfwd_cfwd_composed
  unset _fr13_sfwd_u8_cfwd_composed
  unset _fr13_sfwd_conv_postprep_profile
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.byte_ab.jsonl" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.live_pass.json"
elif [[ "$_fr13_sfwd_conv_postprep_byte" == "1" ]]; then
  _fr13_sfwd_conv_postprep_byte_profile=invalid
  if [[ "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" \
        && "${ENFORCE_EAGER:-0}" == "1" \
        && "${FR13_DRAFT_VOCAB_ROOT:-0}" == "1" \
        && "${FR13_DRAFT_VOCAB_K:-65536}" == "65536" \
        && "${FR13_DRAFT_VOCAB_BLOCKS:-}" == "/workspace/scripts/fr13_dvk_subset_blocks.json" \
        && "${FR13_RING_EXPORT:-1}" == "1" \
        && "${FR13_FLAGS_INKERNEL:-1}" == "1" \
        && "${FR13_TREE_RUNROW_INIT:-1}" == "1" \
        && "${FR13_TREE_CONV_FUSED:-1}" == "1" \
        && "${FR13_CONV_WB_BATCHED:-0}" == "1" \
        && "${FR13_FIXED32_CONV_SOURCE_BATCH:-0}" == "0" \
        && "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" == "0" ]]; then
    if [[ "$MAX_NUM_SEQS" == "1" \
          && "${SWE_CONCURRENCY:-}" == "1" \
          && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "1" \
          && "${FR13_FA2_QROW16_PRODUCTION:-0}" == "1" \
          && "${FR13_FA2_QROW16_SO_SHA256:-}" == "1649fbe9c6886147710dc9be97567bffcac36175c26742b752be9be50c2cbb86" \
          && "${FR13_FA2_QROW16_LIVE_PASS_SHA256:-}" == "36940fd43d11399529d1bfe7e11baa9961907193267f3bb43d41057328737b77" ]]; then
      if [[ "$_fr13_sfwd_embed_gate" == "1" ]]; then
        _fr13_sfwd_conv_postprep_byte_profile=embedded_b1
      else
        _fr13_sfwd_conv_postprep_byte_profile=standalone_b1
      fi
    elif [[ "$_fr13_sfwd_embed_gate" == "1" \
            && "$MAX_NUM_SEQS" == "4" \
            && "${SWE_CONCURRENCY:-}" == "4" \
            && "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" == "0" \
            && "${FR13_FA2_QROW16_PRODUCTION:-0}" == "0" \
            && -z "${FR13_FA2_QROW32_B1_LIVE_AB_ARM:-}" \
            && -z "${FR13_FA2_QROW32_B1_PRODUCTION_ARM:-}" \
            && "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "stock" \
            && "${FR13_FIXED32_CUTLASS_WAVE_PRODUCTION:-0}" == "0" ]]; then
      _fr13_sfwd_conv_postprep_byte_profile=embedded_b4
    fi
  fi
  if [[ "$_fr13_sfwd_conv_postprep_byte_profile" == "invalid" ]]; then
    echo "SFWD conv/post-prep byte gate requires exact Hydra27 physical32 K64/root1 eager B1, or embedded-gate exact B4" >&2
    exit 2
  fi
  if [[ "$_fr13_sfwd_nodegroup8_direct" == "1" \
        && "$_fr13_sfwd_conv_postprep_byte_profile" != "standalone_b1" \
        && "$_fr13_sfwd_conv_postprep_byte_profile" != "embedded_b1" ]]; then
    echo "direct nodegroup8 byte gate requires exact Hydra27 B1" >&2
    exit 2
  fi
  _fr13_sfwd_conv_postprep_cutlass_ok=0
  if [[ "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "stock" \
        || ( "$_fr13_sfwd_conv_postprep_byte_profile" != "embedded_b4" \
             && "${FR13_FIXED32_CUTLASS_WAVE:-stock}" == "identity_wide256_fullgrid_b1_byte_ab" ) ]]; then
    _fr13_sfwd_conv_postprep_cutlass_ok=1
  fi
  if [[ "$_fr13_batch_gdn_diagnostic_count" != "0" \
        || "$_fr13_batch_gdn_production" != "0" \
        || -n "$_fr13_batch_gdn_bv_candidate" \
        || -n "$_fr13_batch_gdn_bv_production" \
        || -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" \
        || "$_fr13_sfwd_conv_postprep_cutlass_ok" != "1" \
        || "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" != "0" \
        || "${FR13_DRAFT_HEAD_M32_PRODUCTION:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE_PRODUCTION:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_PRODUCTION:-0}" != "0" ]]; then
    echo "SFWD conv/post-prep byte gate inherited an incompatible kernel arm" >&2
    exit 2
  fi
  [[ -z "$FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_JSON" \
     && -z "$FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_SHA256" \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH" == /workspace/* \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ \
     && "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_COMMIT" == "$(git rev-parse HEAD)" ]] || {
    echo "SFWD conv/post-prep byte gate requires source-manifest-only credentials" >&2
    exit 2
  }
  _fr13_sfwd_conv_manifest_host="$REPO/${FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH#/workspace/}"
  [[ -f "$_fr13_sfwd_conv_manifest_host" \
     && ! -L "$_fr13_sfwd_conv_manifest_host" \
     && "$(stat -c '%h' "$_fr13_sfwd_conv_manifest_host")" == "1" \
     && "$(sha256sum "$_fr13_sfwd_conv_manifest_host" | awk '{print $1}')" == "$FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_SHA256" ]] || {
    echo "SFWD conv/post-prep source manifest is missing or changed" >&2
    exit 2
  }
  cp -- "$_fr13_sfwd_conv_manifest_host" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.source_manifest.json"
  printf '1\n' > "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep_byte_ab.enabled"
  chmod 0400 \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.source_manifest.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep_byte_ab.enabled"
  FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH=/logs/fr13_fixed32_sfwd_conv_postprep.source_manifest.json
  FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH=/logs/fr13_fixed32_sfwd_state_fusion.real_event.arm
  FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH=/logs/fr13_fixed32_sfwd_state_fusion.real_event.arm
  if [[ "$_fr13_sfwd_embed_gate" == "1" ]]; then
    FR13_FIXED32_SFWD_CONV_POSTPREP_BYTE_AB_PATH=/logs/fr13_fixed32_sfwd_embedded_gate.byte_ab.jsonl
    FR13_FIXED32_SFWD_CONV_POSTPREP_PASS_PATH=/logs/fr13_fixed32_sfwd_embedded_gate.live_pass.json
  fi
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.byte_ab.jsonl" \
    "$LOG_DIR/fr13_fixed32_sfwd_embedded_gate.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_embedded_gate.byte_ab.jsonl"
  unset _fr13_sfwd_conv_postprep_byte_profile
  unset _fr13_sfwd_conv_postprep_cutlass_ok
elif [[ "$_fr13_sfwd_prior_reuse" == "1" ]]; then
  if [[ -z "${FR13_FIXED32_MODE:-}" \
        || "$MAX_NUM_SEQS" != "1" \
        || "${SWE_CONCURRENCY:-}" != "1" \
        || "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" != "1" \
        || "${ENFORCE_EAGER:-0}" != "1" \
        || "${FR13_DRAFT_VOCAB_ROOT:-0}" != "1" \
        || "${FR13_DRAFT_VOCAB_K:-65536}" != "65536" \
        || "${FR13_DRAFT_VOCAB_BLOCKS:-}" != "/workspace/scripts/fr13_dvk_subset_blocks.json" \
        || "${FR13_RING_EXPORT:-1}" != "1" \
        || "${FR13_FLAGS_INKERNEL:-1}" != "1" \
        || "${FR13_TREE_RUNROW_INIT:-1}" != "1" \
        || "${FR13_TREE_CONV_FUSED:-1}" != "1" \
        || "${FR13_CONV_WB_BATCHED:-0}" != "1" \
        || "${FR13_FIXED32_CONV_SOURCE_BATCH:-0}" != "0" ]]; then
    echo "SFWD prior-reuse requires exact K64/root1 eager fixed32 B1" >&2
    exit 2
  fi
  if [[ "$_fr13_batch_gdn_diagnostic_count" != "0" \
        || "$_fr13_batch_gdn_production" != "0" \
        || -n "$_fr13_batch_gdn_bv_candidate" \
        || -n "$_fr13_batch_gdn_bv_production" \
        || -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" \
        || "${FR13_FIXED32_CUTLASS_WAVE:-stock}" != "stock" \
        || "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" != "0" \
        || "${FR13_DRAFT_HEAD_M32_PRODUCTION:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE_PRODUCTION:-0}" != "0" \
        || "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" != "0" \
        || "${FR13_FA2_QROW16_PRODUCTION:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_PRODUCTION:-0}" != "0" ]]; then
    echo "SFWD prior-reuse must be the only SFWD candidate and kernel route" >&2
    exit 2
  fi
  [[ "$FR13_FIXED32_SFWD_PRIOR_REUSE_SOURCE_MANIFEST_PATH" == /workspace/* \
     && "$FR13_FIXED32_SFWD_PRIOR_REUSE_SOURCE_MANIFEST_SHA256" =~ ^[0-9a-f]{64}$ \
     && "$FR13_FIXED32_SFWD_PRIOR_REUSE_SOURCE_COMMIT" =~ ^[0-9a-f]{40}$ ]] || {
    echo "SFWD prior-reuse requires bound source-manifest credentials" >&2
    exit 2
  }
  _fr13_sfwd_prior_manifest_host="$REPO/${FR13_FIXED32_SFWD_PRIOR_REUSE_SOURCE_MANIFEST_PATH#/workspace/}"
  [[ -f "$_fr13_sfwd_prior_manifest_host" \
     && ! -L "$_fr13_sfwd_prior_manifest_host" \
     && "$(sha256sum "$_fr13_sfwd_prior_manifest_host" | awk '{print $1}')" == "$FR13_FIXED32_SFWD_PRIOR_REUSE_SOURCE_MANIFEST_SHA256" ]] || {
    echo "SFWD prior-reuse source manifest is missing or changed" >&2
    exit 2
  }
  cp -- "$_fr13_sfwd_prior_manifest_host" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.source_manifest.json"
  printf '1\n' > "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse_byte_ab.enabled"
  chmod 0400 \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.source_manifest.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse_byte_ab.enabled"
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.byte_ab.jsonl"
  FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH=/logs/fr13_fixed32_sfwd_state_fusion.real_event.arm
elif [[ "$_fr13_sfwd_b4_byte_ab" == "1" ]]; then
  if [[ -z "${FR13_FIXED32_MODE:-}" \
        || "$MAX_NUM_SEQS" != "4" \
        || "${SWE_CONCURRENCY:-}" != "4" \
        || "${ENFORCE_EAGER:-0}" != "1" \
        || "${FR13_DRAFT_VOCAB_ROOT:-0}" != "0" \
        || "${FR13_DRAFT_VOCAB_K:-65536}" != "0" \
        || "${FR13_NEEDS_ALLOW:-}" != "FR13_DRAFT_VOCAB_K=0" \
        || "${FR13_RING_EXPORT:-1}" != "1" \
        || "${FR13_FLAGS_INKERNEL:-1}" != "1" \
        || "${FR13_TREE_RUNROW_INIT:-1}" != "1" \
        || "${FR13_TREE_CONV_FUSED:-1}" != "1" \
        || "${FR13_CONV_WB_BATCHED:-0}" != "1" \
        || "${FR13_FIXED32_CONV_SOURCE_BATCH:-0}" != "1" ]]; then
    echo "SFWD state-fusion gate requires exact4 B4 full-vocabulary eager fixed32 source staging" >&2
    exit 2
  fi
  if [[ "$_fr13_batch_gdn_diagnostic_count" != "0" \
        || "$_fr13_batch_gdn_production" != "0" \
        || -n "$_fr13_batch_gdn_bv_candidate" \
        || -n "$_fr13_batch_gdn_bv_production" \
        || -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" \
        || "${FR13_FIXED32_CUTLASS_WAVE:-stock}" != "stock" \
        || "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" != "0" \
        || "${FR13_DRAFT_HEAD_M32_PRODUCTION:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE_PRODUCTION:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_PRODUCTION:-0}" != "0" ]]; then
    echo "SFWD state-fusion byte gate must be the only kernel candidate" >&2
    exit 2
  fi
  printf '1\n' > "$LOG_DIR/fr13_fixed32_sfwd_state_fusion_byte_ab.enabled"
  chmod 400 "$LOG_DIR/fr13_fixed32_sfwd_state_fusion_byte_ab.enabled"
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.byte_ab.jsonl" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.sha256" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_engagement.json"
  FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH=/logs/fr13_fixed32_sfwd_state_fusion.real_event.arm
elif [[ "$_fr13_sfwd_production" == "1" ]]; then
  if [[ ( "${FR13_FIXED32_MODE:-}" != "tail6_fixed32" \
          && "${FR13_FIXED32_MODE:-}" != "hydra27_fixed32" ) \
        || "$MAX_NUM_SEQS" != "1" \
        || "${SWE_CONCURRENCY:-}" != "1" \
        || "${FR13_FIXED32_B1_DIAGNOSTIC:-0}" != "0" \
        || "${ENFORCE_EAGER:-0}" != "1" \
        || "${FR13_DRAFT_VOCAB_ROOT:-0}" != "1" \
        || "${FR13_DRAFT_VOCAB_K:-65536}" != "65536" \
        || "${FR13_RING_EXPORT:-1}" != "1" \
        || "${FR13_FLAGS_INKERNEL:-1}" != "1" \
        || "${FR13_TREE_RUNROW_INIT:-1}" != "1" \
        || "${FR13_TREE_CONV_FUSED:-1}" != "1" \
        || "${FR13_CONV_WB_BATCHED:-0}" != "1" \
        || "${FR13_FIXED32_CONV_SOURCE_BATCH:-0}" != "0" \
        || "${FR13_FA2_QROW16_LIVE_PAGED_AB:-0}" != "0" \
        || "${FR13_FA2_QROW16_PRODUCTION:-0}" != "1" ]]; then
    echo "SFWD production requires exact K64 B1 eager fixed32 with qrow16 production" >&2
    exit 2
  fi
  if [[ "$_fr13_batch_gdn_diagnostic_count" != "0" \
        || "$_fr13_batch_gdn_production" != "0" \
        || -n "$_fr13_batch_gdn_bv_candidate" \
        || -n "$_fr13_batch_gdn_bv_production" \
        || -n "$_fr13_gdn_path_bv_candidate" \
        || -n "$_fr13_gdn_path_bv_production" \
        || "${FR13_FIXED32_CUTLASS_WAVE:-stock}" != "stock" \
        || "${FR13_DRAFT_HEAD_M32_LIVE_AB:-0}" != "0" \
        || "${FR13_DRAFT_HEAD_M32_PRODUCTION:-0}" != "0" \
        || "${FR13_FIXED32_TAW_NATIVE_PRECOMPUTE:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_LIVE_AB:-0}" != "0" \
        || "${FR13_DFWD_UNIFIED_BM8_PRODUCTION:-0}" != "0" ]]; then
    echo "SFWD production permits qrow16 and source-gated TAW production only" >&2
    exit 2
  fi
  [[ "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_JSON" == /* \
     && -f "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_JSON" \
     && ! -L "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_JSON" \
     && "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ ]] || {
    echo "SFWD production requires a pinned regular B1 live PASS" >&2
    exit 2
  }
  python3 scripts/fr13_sfwd_state_fusion_pass.py validate \
    --live-result "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_JSON" \
    --expected-live-sha256 "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_SHA256" \
    --kernel-source src/lumo_flywheel_serving/fr10_gdn_tree_kernel.py \
    >/dev/null
  cp -- "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_JSON" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.json"
  printf '%s\n' "$FR13_FIXED32_SFWD_STATE_FUSION_LIVE_PASS_SHA256" \
    > "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.sha256"
  printf '1\n' > "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production.arm"
  chmod 400 \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.sha256" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production.arm"
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.byte_ab.jsonl" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_engagement.json"
  FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH=
else
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.real_event.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.byte_ab.jsonl" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_pass.sha256" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production.arm" \
    "$LOG_DIR/fr13_fixed32_sfwd_state_fusion.production_engagement.json" \
    2>/dev/null || true
  FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH=
fi
export FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH
if [[ "$_fr13_sfwd_conv_postprep" != "1" \
      && "$_fr13_sfwd_conv_postprep_byte" != "1" ]]; then
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.source_manifest.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.production_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_conv_postprep.byte_ab.jsonl" \
    2>/dev/null || true
  FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH=
fi
export FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH
if [[ "$_fr13_sfwd_prior_reuse" != "1" ]]; then
  rm -f \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse_byte_ab.enabled" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.source_manifest.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.live_pass.json" \
    "$LOG_DIR/fr13_fixed32_sfwd_prior_reuse.byte_ab.jsonl" \
    2>/dev/null || true
fi
if [[ "$_fr13_batch_gdn_production" == "1" ]]; then
  [[ -n "${FR13_FIXED32_MODE:-}" ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_PRODUCTION requires FR13_FIXED32_MODE" >&2; exit 2; }
  [[ "$MAX_NUM_SEQS" =~ ^[234]$ ]] \
    || { echo "FR13_FIXED32_BATCH_GDN_PRODUCTION requires MAX_NUM_SEQS=2, 3, or 4" >&2; exit 2; }
  if [[ -n "$_fr13_batch_gdn_bv_production" ]]; then
    [[ "$MAX_NUM_SEQS" == "4" ]] \
      || { echo "FR13 fixed32 batched B4 GDN production requires MAX_NUM_SEQS=4" >&2; exit 2; }
    if [[ "$_fr13_batch_gdn_bv_production" == "8" ]]; then
      [[ "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" \
         || "${FR13_FIXED32_MODE:-}" == "hydra27_fixed32" ]] \
        || { echo "FR13 fixed32 batched BV8 production requires a qualified fixed32 mode" >&2; exit 2; }
    else
      [[ "${FR13_FIXED32_MODE:-}" == "tail6_fixed32" ]] \
        || { echo "FR13 fixed32 batched BV64 production requires tail6_fixed32" >&2; exit 2; }
    fi
    [[ "${ENFORCE_EAGER:-0}" == "0" \
       && "${CUDAGRAPH_MODE:-}" == "FULL_AND_PIECEWISE" ]] \
      || { echo "FR13 fixed32 batched B4 GDN production requires the FULL graph runtime" >&2; exit 2; }
    if [[ "$_fr13_batch_gdn_bv_production" == "8" ]]; then
      [[ "${FR10_METRICS:-0}" == "1" ]] \
        || { echo "FR13 fixed32 batched BV8 production requires FR10_METRICS=1" >&2; exit 2; }
      [[ -f "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
         && ! -L "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
         && -f "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" \
         && ! -L "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" ]] \
        || { echo "FR13 fixed32 batched BV8 production requires the pinned gate runtime closure" >&2; exit 2; }
    fi
    [[ -f "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
       && ! -L "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
       && "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" =~ ^[0-9a-f]{64}$ \
       && -f "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
       && ! -L "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
       && "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" =~ ^[0-9a-f]{64}$ ]] \
      || { echo "FR13 fixed32 batched B4 GDN production requires a pinned completed exact4 graph gate" >&2; exit 2; }
    rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json"
    if [[ "$_fr13_batch_gdn_bv_production" == "8" ]]; then
      python3 scripts/fr13_b4_gdn_bv8_pass.py install \
        --live-result "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
        --expected-live-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
        --gate-verdict "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
        --expected-gate-verdict-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
        --kernel-source src/lumo_flywheel_serving/fr10_gdn_tree_kernel.py \
        --runtime-manifest "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
        --gate-runner "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" \
        --out "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" \
        || { echo "FR13 fixed32 batched BV8 graph PASS attestation failed" >&2; exit 2; }
    else
      python3 scripts/fr13_b4_gdn_bv64_pass.py install \
        --live-result "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
        --expected-live-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
        --gate-verdict "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
        --expected-gate-verdict-sha256 "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
        --kernel-source src/lumo_flywheel_serving/fr10_gdn_tree_kernel.py \
        --out "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" \
        || { echo "FR13 fixed32 BV64 graph PASS attestation failed" >&2; exit 2; }
    fi
    printf '%s\n' "$_fr13_batch_gdn_bv_production" \
      > "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag"
    chmod 400 "$LOG_DIR/fr13_fixed32_batch_gdn_bv_production.flag"
  else
    [[ -z "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_JSON" \
       && -z "$FR13_FIXED32_BATCH_GDN_GRAPH_LIVE_PASS_SHA256" \
       && -z "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_JSON" \
       && -z "$FR13_FIXED32_BATCH_GDN_GRAPH_GATE_VERDICT_SHA256" \
       && -z "$FR13_FIXED32_BATCH_GDN_RUNTIME_MANIFEST_JSON" \
       && -z "$FR13_FIXED32_BATCH_GDN_GATE_RUNNER" ]] \
      || { echo "FR13 graph PASS inputs are exact B4 production only" >&2; exit 2; }
    [[ -f "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" \
       && ! -L "$LOG_DIR/fr13_fixed32_batch_gdn_byte_ab.pass.json" ]] \
      || { echo "FR13_FIXED32_BATCH_GDN_PRODUCTION requires a regular live-gate PASS record" >&2; exit 2; }
  fi
  echo "1" > "$LOG_DIR/fr13_fixed32_batch_gdn_production.arm"
else
  rm -f "$LOG_DIR/fr13_fixed32_batch_gdn_production.arm" 2>/dev/null || true
fi
# FR13_SUBTREE_PARALLEL sidecars. EngineCore receives a curated environment
# that drops these FR13_* gates, so env-only reads silently select the
# monolithic scan. The worker-visible /logs arms are the serving authority;
# env reads remain supported by the kernel for offline/eager use.
_fr13_subtree_parallel="${FR13_SUBTREE_PARALLEL:-1}"
_fr13_subtree_selfcheck="${FR13_SUBTREE_PARALLEL_SELFCHECK:-0}"
case "$_fr13_subtree_parallel" in
  0|1) ;;
  *) echo "FR13_SUBTREE_PARALLEL must be 0 or 1" >&2; exit 2 ;;
esac
case "$_fr13_subtree_selfcheck" in
  0|1) ;;
  *) echo "FR13_SUBTREE_PARALLEL_SELFCHECK must be 0 or 1" >&2; exit 2 ;;
esac
if [[ "$_fr13_subtree_selfcheck" == "1" && "$_fr13_subtree_parallel" != "1" ]]; then
  echo "FR13_SUBTREE_PARALLEL_SELFCHECK=1 requires FR13_SUBTREE_PARALLEL=1" >&2
  exit 2
fi
# FR13_MAMBA_SPEC_BLOCKS_CDIV (default 0=OFF, PATCH-TIME): rewrites MambaSpec's
# num_speculative_blocks from num_speculative_tokens (31) to
# cdiv(num_speculative_tokens, mamba_block_size) (=1 at 31/1024). Read only by
# fr10_phase4_patch_vllm_tree_gdn.py inside the container, so the -e line below
# is what actually carries it. The patcher's slot-demand preflight refuses the
# ON state while the GDN spec path still indexes one mamba state slot per draft
# node -- see fr13_required_tree_flags.sh for the evidence.
case "${FR13_MAMBA_SPEC_BLOCKS_CDIV:-0}" in
  0|1) ;;
  *) echo "FR13_MAMBA_SPEC_BLOCKS_CDIV must be 0 or 1" >&2; exit 2 ;;
esac
if [[ ( "$_fr13_batch_gdn_byte_ab" == "1" \
        || "$_fr13_batch_gdn_graph_byte_ab" == "1" \
        || "$_fr13_batch_gdn_production" == "1" ) \
      && "$_fr13_subtree_parallel" != "1" ]]; then
  echo "FR13 fixed32 batched GDN requires FR13_SUBTREE_PARALLEL=1" >&2
  exit 2
fi
if [[ ( "$_fr13_batch_gdn_byte_ab" == "1" \
        || "$_fr13_batch_gdn_graph_byte_ab" == "1" \
        || "$_fr13_batch_gdn_production" == "1" ) \
      && "$_fr13_subtree_selfcheck" == "1" ]]; then
  echo "FR13 fixed32 batched GDN is incompatible with FR13_SUBTREE_PARALLEL_SELFCHECK=1" >&2
  exit 2
fi
if [[ "$_fr13_subtree_selfcheck" == "1" && "${ENFORCE_EAGER:-0}" != "1" ]]; then
  echo "FR13_SUBTREE_PARALLEL_SELFCHECK=1 requires ENFORCE_EAGER=1" >&2
  exit 2
fi
if [[ "$_fr13_subtree_parallel" == "1" ]]; then
  : > "$LOG_DIR/fr13_subtree_parallel.arm"
else
  rm -f "$LOG_DIR/fr13_subtree_parallel.arm" 2>/dev/null || true
fi
if [[ "$_fr13_subtree_selfcheck" == "1" ]]; then
  : > "$LOG_DIR/fr13_subtree_parallel_selfcheck.arm"
else
  rm -f "$LOG_DIR/fr13_subtree_parallel_selfcheck.arm" 2>/dev/null || true
fi
# FR13_COMMIT_ARGMAX_GATE sidecar (same worker-env-drop workaround): the worker curation drops the flag
# (keeps only *_DUMP). The patched rejection_sampler reads this sidecar OR the (dropped) env.
if [[ "${FR13_COMMIT_ARGMAX_GATE:-0}" == "1" ]]; then
  : > "$LOG_DIR/fr13_commit_argmax_gate.arm"
else
  rm -f "$LOG_DIR/fr13_commit_argmax_gate.arm" 2>/dev/null || true
fi
# FR13_DEVICE_MULTIDRAFT off-sidecar (worker-env-drop-proof): DEVICE_MULTIDRAFT defaults ON and is dropped
# from the worker env, so FR13_DEVICE_MULTIDRAFT=0 can't turn it off via env. This sidecar forces the
# Python committer loop (needed for the CAG gate; also a decisive device-vs-Python garble A/B).
if [[ "${FR13_DEVICE_MULTIDRAFT:-1}" == "0" ]]; then
  : > "$LOG_DIR/fr13_device_multidraft_off.arm"
else
  rm -f "$LOG_DIR/fr13_device_multidraft_off.arm" 2>/dev/null || true
fi
# FR13_DRAFT_SOURCE=merged sidecar (same worker-env-drop workaround): the worker drops FR13_* env, so
# the MTP-k+Arctic-suffix merged drafter seam (fr10_phase4_patch_vllm_tree_gdn.py) reads THIS sidecar
# to enable merged mode. Default (absent/mtp) => byte-identical locked cat9 drafter, zero arctic.
if [[ "${FR13_DRAFT_SOURCE:-mtp}" == "merged" ]]; then
  : > "$LOG_DIR/fr13_draft_source_merged.arm"
else
  rm -f "$LOG_DIR/fr13_draft_source_merged.arm" 2>/dev/null || true
fi
# accept>5 TAIL mode sidecar (same worker-env-drop workaround): caps native MTP forwards at the head
# (head_depth-1) + appends the deep Arctic chain (depths head_depth..wide_D-1). REQUIRES the merged
# sidecar too (the Arctic cache lifecycle rides on the merged runner hook). Absent => no tail.
if [[ "${FR13_TAIL_MODE:-0}" == "1" ]]; then
  : > "$LOG_DIR/fr13_tail_mode.arm"
  echo "[launch] TAIL mode ON -> /logs/fr13_tail_mode.arm (head_depth=5 + arctic chain to wide_D)"
else
  rm -f "$LOG_DIR/fr13_tail_mode.arm" 2>/dev/null || true
fi
# HYDRA23 exact-shape sidecar. The worker strips FR13_* variables, while the
# patched drafter must fail loud if its full-path Arctic columns are paired
# with any other tree.
if [[ "${FR13_HYDRA23:-0}" == "1" ]]; then
  : > "$LOG_DIR/fr13_hydra23.arm"
  echo "[launch] HYDRA23 ON -> /logs/fr13_hydra23.arm (root-rank1 rescue chain length 4)"
else
  rm -f "$LOG_DIR/fr13_hydra23.arm" 2>/dev/null || true
fi
# Direction-2 d6-branch: bridge FR13_TAIL_BRANCHES/DEPTHS past the worker env-strip via a /logs sidecar
# (value-carrying, like the prewarm corpus). decide_tail reads "<branches> <depths>". Absent => spine-only.
if [[ -n "${FR13_TAIL_BRANCHES:-}" && "${FR13_TAIL_BRANCHES:-0}" != "0" ]]; then
  echo "${FR13_TAIL_BRANCHES} ${FR13_TAIL_BRANCH_DEPTHS:-0}" > "$LOG_DIR/fr13_tail_branches.cfg"
  echo "[launch] TAIL branches ON -> /logs/fr13_tail_branches.cfg (${FR13_TAIL_BRANCHES} branches x ${FR13_TAIL_BRANCH_DEPTHS:-0} depths)"
else
  rm -f "$LOG_DIR/fr13_tail_branches.cfg" 2>/dev/null || true
fi
# PRE-WARM corpus sidecar (design §6b): worker drops FR13_* env, so copy the host corpus into /logs (mounted)
# and maybe_prewarm() reads the fixed /logs/fr13_prewarm_corpus.jsonl. Absent => cold trie (never-regress).
if [[ -n "${FR13_PREWARM_TRIE:-}" && -f "${FR13_PREWARM_TRIE}" ]]; then
  cp "$FR13_PREWARM_TRIE" "$LOG_DIR/fr13_prewarm_corpus.jsonl" && echo "[launch] pre-warm corpus -> /logs ($(wc -l < "$FR13_PREWARM_TRIE") seqs)"
else
  rm -f "$LOG_DIR/fr13_prewarm_corpus.jsonl" 2>/dev/null || true
fi
if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  _fixed32_same_name_containers=$(
    docker ps -aq --filter "name=^/${CONTAINER}$"
  ) || {
    echo "unable to enumerate the exact fixed32 container name" >&2
    exit 2
  }
  if [[ -n "$_fixed32_same_name_containers" ]]; then
    echo "fixed32 exact container name already exists: $CONTAINER" >&2
    exit 2
  fi
  unset _fixed32_same_name_containers
else
  docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
fi

set -a
if (( _FR13_LOCAL_ENV_SOURCED == 0 )) && [[ -f "$REPO/.lumo.local.env" ]]; then
  source "$REPO/.lumo.local.env"
fi
set +a
if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  [[ "${VLLM_DISABLE_REQUEST_ID_RANDOMIZATION:-1}" == "1" ]] \
    || {
      echo "fixed32 request-ID binding changed after local environment loading" >&2
      exit 2
    }
  VLLM_DISABLE_REQUEST_ID_RANDOMIZATION=1
  export VLLM_DISABLE_REQUEST_ID_RANDOMIZATION
fi

_lumo_truthy() {
  case "${1,,}" in
    1|true|yes|on) return 0 ;;
    *) return 1 ;;
  esac
}

LUMO_NSYS_WRAP_VLLM=${LUMO_NSYS_WRAP_VLLM:-0}
LUMO_NSYS_BIN=${LUMO_NSYS_BIN:-/opt/nvidia/nsight-systems-cli/2026.2.1/bin/nsys}
LUMO_NSYS_DELAY_S=${LUMO_NSYS_DELAY_S:-600}
LUMO_NSYS_DURATION_S=${LUMO_NSYS_DURATION_S:-150}
# Periodic CUPTI buffer flush (ms). Without it, per-kernel records (incl. graph
# node-level kernels) are dropped as "incomplete" at the delayed-duration session
# stop on GB10 (fr13_b1_profile_bind: 55k/78k events dropped, zero kernel rows).
LUMO_NSYS_FLUSH_MS=${LUMO_NSYS_FLUSH_MS:-100}
# Semicolon-separated lines appended to the in-container nsys user config
# ("$nsys -z"). Default works around the GB10 drop class where ALL per-kernel
# rows are "incomplete CUPTI events dropped ... GPU timestamp information have
# not been retrieved" even with periodic flushes (NVIDIA-documented
# CuptiUseRawGpuTimestamps=false workaround; fr13_b1_profile_node: 102,320
# dropped with --cuda-flush-interval 100 and zero kernel tables).
LUMO_NSYS_CONFIG_DIRECTIVES=${LUMO_NSYS_CONFIG_DIRECTIVES:-CuptiUseRawGpuTimestamps=false}
# nsys --trace value. On GB10 + CUDA 13 the default 'cuda' engages the HARDWARE
# trace engine for kernel records; in delayed-duration sessions ALL kernel rows
# are then dropped ("GPU timestamp information have not been retrieved").
# 'cuda,cuda-sw' forces the software CUPTI kernel-record path (memcpy/memset/
# runtime rows always survived; only hw-trace kernel rows dropped).
LUMO_NSYS_TRACE=${LUMO_NSYS_TRACE:-cuda,nvtx}
LUMO_NSYS_OUTPUT=${LUMO_NSYS_OUTPUT:-/logs/nsys_vllm_${CONTAINER}}
NSYS_DOCKER_ARGS=()
if _lumo_truthy "$LUMO_NSYS_WRAP_VLLM"; then
  if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
    [[ "${LUMO_NSYS_SESSION_NAME:-}" =~ \
       ^fr13-fixed32-[0-9]{8}T[0-9]{6}Z-p[1-9][0-9]*$ ]] \
      || {
        echo "fixed32 attribution requires a pinned run-unique Nsight session name" >&2
        exit 2
      }
  fi
  for nsight_mount in /opt/nvidia /usr/local/cuda-13.0; do
    if [[ ! -e "$nsight_mount" ]]; then
      echo "LUMO_NSYS_WRAP_VLLM enabled but Nsight mount path is missing: $nsight_mount" >&2
      exit 2
    fi
    NSYS_DOCKER_ARGS+=(-v "$nsight_mount:$nsight_mount:ro")
  done
fi

# stale dcgm-sampler sweep (2026-07-24): gate-era sample_dcgm_during_task
# processes survive force-teardowns holding /dev/nvidia* and kill the NEXT
# boot pre-health (reference_dcgm_samplers_block_mem_recovery; observed 24h
# survivors). Sweep BEFORE memory recovery so the device is actually free.
pkill -f "sample_dcgm_during_task.py" 2>/dev/null && sleep 2 || true

PYTHONPATH="$REPO/src${PYTHONPATH:+:$PYTHONPATH}" python3 - <<'PY'
from lumo_flywheel_serving.model_server import recover_host_memory

recover_host_memory()
PY

free -h
python3 - <<'PY'
from pathlib import Path

fields = {}
for line in Path("/proc/meminfo").read_text().splitlines():
    key, value = line.split(":", 1)
    fields[key] = int(value.strip().split()[0])

available_gib = fields.get("MemAvailable", 0) / 1024 / 1024
swap_used_kib = fields.get("SwapTotal", 0) - fields.get("SwapFree", 0)
if available_gib < 80 or swap_used_kib != 0:
    raise SystemExit(
        "FR13 launch aborted: host memory recovery did not produce "
        f"MemAvailable>=80GiB and swap_used==0; "
        f"MemAvailable={available_gib:.2f}GiB "
        f"swap_used={swap_used_kib / 1024 / 1024:.2f}GiB"
    )
PY

# FR13 §48 class-9 trap fix: auto-forward EVERY experiment flag set in this shell
# (FR<N>_*, LUMO_*, VLLM_*) into the container so a new flag can never be silently
# absent in-container (the patcher reads flags at patch time inside the container).
# Placed BEFORE the explicit -e list: docker takes the LAST occurrence of a name,
# so the explicit entries below keep their ${VAR:-default} semantics unchanged.
# FR13_TORCHPROF: arm vLLM's BUILT-IN torch profiler (with_stack defaults
# TRUE in-engine) via serve CLI config — engine config, not env, so the
# worker-env-drop class cannot touch it. Window control = POST /start_profile
# + /stop_profile (routes attach only when this config is set). DIAGNOSTIC
# ARM ONLY: in-window numbers carry capture overhead; label everything
# derived from it diagnostic-only, never compare as clean speed.
FR13_PROFILER_FLAGS=""
if [[ "${FR13_TORCHPROF:-0}" == "1" ]]; then
  FR13_PROFILER_FLAGS="--profiler-config.profiler=torch --profiler-config.torch_profiler_dir=/logs/torchprof"
fi

FR13_ENV_FORWARD_ARGS=()
while IFS= read -r _v; do
  [[ "$_v" == "FR13_FIXED32_INGRESS_SECRET_FILE" \
     || "$_v" == "FR13_FIXED32_MIDDLEWARE_FLAGS" \
     || "$_v" == "FR13_FIXED32_B1_FP8_QUANT_REGCACHE_SO" \
     || "$_v" == "FR13_FIXED32_B1_FP8_QUANT_REGCACHE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_SO" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_RESOURCE_CREDENTIAL" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_RESOURCE_CREDENTIAL_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_WAVE_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_TAIL23_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_STAGE2_HYDRA27_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_TAIL23_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_TWOM_HYDRA27_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_TAIL23_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_CUTLASS_HYBRID_N5120_HYDRA27_LIVE_PASS_SHA256" \
     || "$_v" == "FR13_FIXED32_GDN_GQA_GROUP3_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_BATCH_GDN_BYTE_AB_REAL_EVENT_PATH" \
     || "$_v" == "FR13_FIXED32_CUTLASS_B4_BYTE_AB_REAL_EVENT_PATH" \
     || "$_v" == "FR13_FIXED32_SFWD_STATE_FUSION_REAL_EVENT_PATH" \
     || "$_v" == "FR13_FIXED32_SFWD_CONV_POSTPREP_SOURCE_MANIFEST_PATH" \
     || "$_v" == "FR13_FIXED32_SFWD_CONV_POSTPREP_LIVE_PASS_JSON" \
     || "$_v" == "FR13_FIXED32_SFWD_CONV_POSTPREP_REAL_EVENT_PATH" \
     || "$_v" == "FR13_DFWD_K64_TOP3_SO" \
     || "$_v" == "FR13_DRAFT_HEAD_M1_R64_U8_SO" \
     || "$_v" == "FR13_DRAFT_HEAD_M4_R64_U8_SO" ]] && continue
  if [[ -n "${FR13_FIXED32_MODE:-}" \
     && "$_v" == "VLLM_DISABLE_REQUEST_ID_RANDOMIZATION" ]]; then
    continue
  fi
  case "$(declare -p "$_v" 2>/dev/null)" in declare\ -a*|declare\ -A*) continue;; esac
  [[ "${!_v}" == *$'\n'* ]] && continue
  FR13_ENV_FORWARD_ARGS+=( -e "${_v}=${!_v}" )
done < <(compgen -v | grep -E '^(FR[0-9]+_|LUMO_|VLLM_)' | sort)

if [[ -n "${FR13_FIXED32_MODE:-}" ]]; then
  [[ -f "$FR13_FIXED32_INGRESS_SECRET_FILE" \
     && ! -L "$FR13_FIXED32_INGRESS_SECRET_FILE" \
     && "$(stat -c '%a' "$FR13_FIXED32_INGRESS_SECRET_FILE")" == "600" ]] \
    || {
      echo "fixed32 ingress secret changed before Docker mount/use" >&2
      exit 2
    }
fi

